// spec: .qa/e2e/specs/monitoring.md (3.1) · кейс: .qa/tests/monitoring/MON-029.md
// seed: tests/seed.user.spec.ts
// Веб-мок ?mock=warm: термостатус 2 (MODERATE), 36.6°C и медленный анализ 260 мс ~30 с (старое правило «медленная модель = нагрев» дало бы сбой через 20 с).
import { test, expect } from '@playwright/test';
import path from 'node:path';
import { startMonitoring, endMonitoring } from '../helpers/monitor';

// Сессия: по умолчанию user (dadayo); QA_MON_AUTH=<имя> — другой файл из .qa/auth (например, когда user.json протух).
test.use({ storageState: path.join(__dirname, `../../../auth/${process.env.QA_MON_AUTH || 'user'}.json`) });
test.setTimeout(150_000);

test.describe('Сбои мониторинга (мок)', () => {
  test('MODERATE: баннер «הטלפון מתחמם», мониторинг продолжается, без сбоя «הטלפון התחמם» #56611b @android @data', async ({ page }) => {
    await startMonitoring(page, 'warm');

    // Баннер-предупреждение с советом (тикет «מה רצוי»: בחימום בינוני — לכל היותר אזהרה עם עצה)
    const banner = page.getByText('הטלפון מתחמם. הניטור ממשיך, אבל כדאי להעביר אותו לצל ולטעון במטען רגיל ולא במטען מהיר.').filter({ visible: true });
    await expect(banner).toBeVisible({ timeout: 25_000 });
    const overheated = page.getByText('הטלפון התחמם').filter({ visible: true });
    const notTracked = page.getByText('לא במעקב').filter({ visible: true });
    await expect(overheated).toHaveCount(0);
    await expect(notTracked).toHaveCount(0);

    // Фаза нагрева закончилась: баннер исчез (он же исчезает, если поднялся сбой — поэтому сразу проверяем, что сбоя нет)
    await expect(banner).toBeHidden({ timeout: 45_000 });
    await expect(overheated).toHaveCount(0);
    await expect(notTracked).toHaveCount(0);
    await expect(page.getByText('תקין', { exact: true }).filter({ visible: true }).first()).toBeVisible({ timeout: 15_000 });

    await endMonitoring(page);
  });
});
